/** Independent C07 source-runtime obligations. No generated results are used as business oracles.
 * Open Questions and unexecuted installed/native gates: r5/contracts/C07/executable-coverage.md. */
import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,readFileSync,writeFileSync,readdirSync,rmSync,existsSync,renameSync,chmodSync,symlinkSync} from 'node:fs';
import path from 'node:path';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {DatabaseSync} from 'node:sqlite';
import {createGenericCompositionOwner} from '../../src/generic/public-sdk.js';
import {parseCoreCommerceSyntax} from '../../src/commerce/commerce-core-syntax.js';
const root=fileURLToPath(new URL('../../../../../../../',import.meta.url));
const cli=fileURLToPath(new URL('../../',import.meta.url));
const base=path.join(root,'implementation/craft-alchlang-generic-applications-2026-10-18-r5');
const contracts=path.join(base,'contracts/C07');
const text=(name:string)=>readFileSync(path.join(contracts,name),'utf8');
const json=(name:string)=>JSON.parse(text(name));
const source=text('request.alch'),profile=json('profile.json'),bounds=json('bounds.json');
const oracle=json('oracle-v1.json'),rows=json('fixture-rows.json');
const wrapper='ReviewDesk.ApproveStoredRequestEntry',query='ReviewDesk.ReadRequestEntry',unique='ReviewDesk.ReadRequestByReferenceEntry';
const entries=[wrapper,query,unique],subject='fixture-reviewer-a';
const wire=(v:unknown)=>new Uint8Array(Buffer.from(JSON.stringify(v)));
const sha=(v:string|Buffer)=>createHash('sha256').update(v).digest('hex');
const code=(e:any)=>e?.diagnostics?.[0]?.code??e?.code??e?.error?.code;
const good=(r:any,outcome:unknown)=>{assert.equal(r.ok,true,JSON.stringify(r));assert.deepEqual(structuredClone(r.outcome),structuredClone(outcome));assert.ok(Number.isSafeInteger(r.fuel_used)&&r.fuel_used>=0);return r;};
const fault=(r:any,wanted:string,phase?:string)=>{assert.equal(r.ok,false,JSON.stringify(r));assert.equal(r.error.code,wanted);if(phase)assert.equal(r.error.phase,phase);assert.ok(Number.isSafeInteger(r.fuel_used)&&r.fuel_used>=0);return r;};
const clone=<T>(v:T):T=>structuredClone(v);
let artifactSequence=0;
function recordArtifacts(out:string,manifest:any){if(!process.env.C07_EVIDENCE_DIR)return;const e=process.env.C07_EVIDENCE_DIR;mkdirSync(e,{recursive:true});const files:any[]=[];function visit(dir:string){for(const item of readdirSync(dir,{withFileTypes:true})){const target=path.join(dir,item.name);assert.equal(item.isSymbolicLink(),false);if(item.isDirectory())visit(target);else files.push({path:path.relative(out,target),sha256:sha(readFileSync(target)),bytes:readFileSync(target).length});}}visit(out);writeFileSync(path.join(e,'artifact-'+String(++artifactSequence).padStart(3,'0')+'.json'),JSON.stringify({manifest,files},null,2)+'\n');}
async function fixture(s=source,p=profile,b=bounds,accepted=true){const dir=mkdtempSync(path.join(tmpdir(),'craft-independent-C07-'));assert.equal(dir.startsWith(root+path.sep),false);mkdirSync(path.join(dir,'contracts'));const sourcePath=path.join(dir,'business.alch'),profilePath=path.join(dir,'profile.json');writeFileSync(sourcePath,s);writeFileSync(profilePath,JSON.stringify(p));writeFileSync(path.join(dir,'contracts/bounds.json'),JSON.stringify(b));const owner:any=createGenericCompositionOwner();try{const handle=await owner.prepare({sourcePath,profilePath});let review:any;if(accepted){review=owner.review(handle,'independent-C07-oracle');owner.accept(handle,{decision_id:'C07-source-test',owner:'independent-C07-oracle',outcome:'accepted',reviewed_digest:review.review_sha256},path.join(dir,'decision.json'));}return{dir,owner,handle,review,sourcePath,profilePath,cleanup:()=>rmSync(dir,{recursive:true,force:true})};}catch(e){rmSync(dir,{recursive:true,force:true});throw e;}}
async function testing():Promise<any>{return import('../../src/generic/testing.js');}
async function setup(options:{source?:string;profile?:any;bounds?:any;rows?:any;grants?:string[];load?:boolean;subjects?:string[]}={}){const f=await fixture(options.source??source,options.profile??profile,options.bounds??bounds);let auth:any,runtime:any;try{const api=await testing();const ids=options.subjects??[subject];const all=options.grants??entries;auth=await api.createGenericAuthFixture(f.owner,f.handle,{ownedDirectory:path.join(f.dir,'auth'),subjects:ids.map((id,index)=>({id,evidence:'independent-evidence-'+index,session:'independent-session-'+index})),grants:ids.flatMap(id=>all.map(entry=>({subject:id,entry})))});const r=await api.prepareGenericFixtureRuntime(f.owner,f.handle,{service:(options.profile??profile).services[0].id,ownedDirectory:path.join(f.dir,'fixture-store'),nativeAuth:auth.nativeAuth});runtime=r.runtime;if(options.load!==false)api.loadGenericFixture(r.fixture,wire(options.rows??rows));return{...f,...r,auth,api,close:async()=>{await runtime.close();await auth.close();f.cleanup();}};}catch(e){if(runtime)await runtime.close();if(auth)await auth.close();f.cleanup();throw e;}}
async function invoke(f:any,entry=wrapper,input:any={id:'23'},actor:any=undefined){const h=f.runtime.entry(entry),prepared=f.runtime.prepareInput(h,wire(input));const a=await f.runtime.authorize(actor===undefined?f.auth.actor(f.runtime,subject,entry):actor,prepared);if(!a.ok)return a;const c=await f.runtime.consume(a.value,prepared);if(!c.ok)return c;return f.runtime.execute(c.value);}
async function rejectSource(s:string,wanted:string|readonly string[]='UnsupportedCapability',p=profile){assert.doesNotThrow(()=>parseCoreCommerceSyntax(s,'business.alch'));await assert.rejects(()=>fixture(s,p),(e:any)=>{assert.ok((Array.isArray(wanted)?wanted:[wanted]).includes(code(e)),String(e));return true;});}
const qWhere='  where stored.id == id';
const qProjection='  project stored.value';
function queryEdit(before:string,after:string){const start=source.indexOf('query ReadRequest:'),end=source.indexOf('query ReadRequestByReference:');assert.ok(start>=0&&end>start);const block=source.slice(start,end);assert.ok(block.includes(before));return source.slice(0,start)+block.replace(before,after)+source.slice(end);}

for(const expected of oracle.business_cases)test('C07 '+expected.id+' through actual protected SQLite source runtime',async()=>{const f=await setup();try{good(await invoke(f,expected.entry,expected.input),expected.expected_outcome);assert.equal(f.runtime.inspect().lookup_attempts,1);assert.equal(f.runtime.inspect().completed_observations,1);assert.equal(f.runtime.inspect().keyed_statement_attempts,1);}finally{await f.close();}});
test('C07 renamed second domain uses unchanged existing Publication Operation',async()=>{const p=json('laboratory-profile.json'),f=await setup({source:text('laboratory.alch'),profile:p,rows:json('laboratory-fixture-rows.json'),grants:['Laboratory.PublishStoredSampleEntry','Laboratory.ReadSampleEntry','Laboratory.ReadSampleByCatalogueEntry']});try{const sample=json('laboratory-fixture-rows.json').rows[0].value.specimen;good(await invoke(f,'Laboratory.PublishStoredSampleEntry',{id:'23'}),{kind:'Returned',value:{published:true,publicationNo:'23',proposal:{tag:'transition',state:'Published',intents:[],machine:'Laboratory.PublicationFlow',branch:'transition:0',reason:'matched'},readings:[sample.readings[2],sample.readings[3],sample.readings[0]],ratings:['4','8','8'],total:'20',result:{tag:'Scored',fields:{total:'20'}},annotation:{manualReview:null}}});assert.equal(f.runtime.inspect().lookup_attempts,1);}finally{await f.close();}});
test('C07 explicit some projection is one Optional layer',async()=>{const f=await setup({source:queryEdit(qProjection,'  project some(stored.value)')});try{good(await invoke(f),oracle.business_cases[0].expected_outcome);good(await invoke(f,query),oracle.business_cases[3].expected_outcome);}finally{await f.close();}});
test('C07 present row projecting none invokes wrapper missing but direct Query returns none',async()=>{const f=await setup({source:queryEdit(qProjection,'  project none')});try{good(await invoke(f),{kind:'Rejected',code:'request-not-found'});good(await invoke(f,query),{kind:'Returned',value:null});}finally{await f.close();}});
test('C07 absent row skips failing full predicate while present row reaches authored fault',async()=>{const f=await setup({source:queryEdit(qWhere,qWhere+' and 1 / 0 > 0')});try{good(await invoke(f,query,{id:'99'}),{kind:'Returned',value:null});fault(await invoke(f,query),'DivideByZero');assert.equal(f.runtime.inspect().lookup_attempts,2);}finally{await f.close();}});
test('C07 duplicate contradictory key equality cannot override first selected lookup proof',async()=>{const f=await setup({source:queryEdit(qWhere,qWhere+' and stored.id == 99')});try{good(await invoke(f,query),{kind:'Returned',value:null});good(await invoke(f),{kind:'Rejected',code:'request-not-found'});assert.equal(f.runtime.inspect().lookup_attempts,2);}finally{await f.close();}});
for(const action of ['reject query-rejected','fail read-unavailable'])test('C07 ordinary Query '+action+' propagates without unavailable provenance',async()=>{const f=await setup({source:queryEdit('  on-missing return none','  on-missing '+action)});try{good(await invoke(f,wrapper,{id:'99'}),{kind:action.startsWith('reject')?'Rejected':'Failed',code:action.split(' ')[1]});}finally{await f.close();}});
for(const[grants,wanted,phase]of [[[], 'PermissionDenied','initial-auth'],[[query],'PermissionDenied','initial-auth'],[[wrapper],'PermissionDenied','child-auth']]as const)test('C07 '+phase+' denies before protected SQL for grants '+grants.join(','),async()=>{const f=await setup({grants:[...grants]});try{fault(await invoke(f),wanted,phase);assert.equal(f.runtime.inspect().lookup_attempts,0);assert.equal(f.runtime.inspect().completed_observations,0);}finally{await f.close();}});
test('C07 null actor is AuthenticationRequired with no storage access',async()=>{const f=await setup();try{fault(await invoke(f,wrapper,{id:'23'},null),'AuthenticationRequired','initial-auth');assert.equal(f.runtime.inspect().lookup_attempts,0);}finally{await f.close();}});
test('C07 genuine permission revocation between authorize and consume denies final Auth',async()=>{const f=await setup();try{const p=f.runtime.prepareInput(f.runtime.entry(wrapper),wire({id:'23'})),a=await f.runtime.authorize(f.auth.actor(f.runtime,subject,wrapper),p);assert.equal(a.ok,true);f.auth.setPermission(subject,wrapper,false);fault(await f.runtime.consume(a.value,p),'PermissionDenied','final-auth');assert.equal(f.runtime.inspect().lookup_attempts,0);await assert.rejects(async()=>f.runtime.consume(a.value,p));}finally{await f.close();}});
test('C07 child scope mismatch denies without silently rewriting genuine actor',async()=>{const s=source.replace('    auth-scope review-desk','    auth-scope query-only-scope'),f=await setup({source:s});try{fault(await invoke(f),'PermissionDenied','child-auth');assert.equal(f.runtime.inspect().lookup_attempts,0);}finally{await f.close();}});
test('C07 caller wire mutation after preparation cannot change captured typed input',async()=>{const f=await setup();try{const bytes=wire({id:'23'}),p=f.runtime.prepareInput(f.runtime.entry(wrapper),bytes);bytes.set(wire({id:'99'}));const a=await f.runtime.authorize(f.auth.actor(f.runtime,subject,wrapper),p);assert.equal(a.ok,true);const t=await f.runtime.consume(a.value,p);assert.equal(t.ok,true);good(await f.runtime.execute(t.value),oracle.business_cases[0].expected_outcome);}finally{await f.close();}});
for(const value of [23,true,null,{},'18446744073709551616'])test('C07 wrong root input '+JSON.stringify(value)+' fails before Auth and read',async()=>{const f=await setup();try{assert.throws(()=>f.runtime.prepareInput(f.runtime.entry(wrapper),wire({id:value})),(e:any)=>{assert.ok(['InputType','InputBound'].includes(e.error?.code),String(e));assert.ok(Number.isSafeInteger(e.fuel_used));return true;});assert.equal(f.runtime.inspect().lookup_attempts,0);}finally{await f.close();}});
test('C07 copied Entry and preparation, swapped authorization and reused transfer carry no authority',async()=>{const f=await setup();try{const e=f.runtime.entry(wrapper);assert.throws(()=>f.runtime.prepareInput({...e},wire({id:'23'})));const p=f.runtime.prepareInput(e,wire({id:'23'}));await assert.rejects(async()=>f.runtime.authorize(f.auth.actor(f.runtime,subject,wrapper),{...p}));const p2=f.runtime.prepareInput(e,wire({id:'24'})),a=await f.runtime.authorize(f.auth.actor(f.runtime,subject,wrapper),p);assert.equal(a.ok,true);await assert.rejects(async()=>f.runtime.consume(a.value,p2));const p3=f.runtime.prepareInput(e,wire({id:'23'})),a3=await f.runtime.authorize(f.auth.actor(f.runtime,subject,wrapper),p3);assert.equal(a3.ok,true);const t=await f.runtime.consume(a3.value,p3);assert.equal(t.ok,true);await assert.rejects(async()=>f.runtime.execute({...t.value}));good(await f.runtime.execute(t.value),oracle.business_cases[0].expected_outcome);await assert.rejects(async()=>f.runtime.execute(t.value));}finally{await f.close();}});
test('C07 concurrent reuse can authorize at most one invocation',async()=>{const f=await setup();try{const p=f.runtime.prepareInput(f.runtime.entry(wrapper),wire({id:'23'})),actor=f.auth.actor(f.runtime,subject,wrapper);const results=await Promise.allSettled([f.runtime.authorize(actor,p),f.runtime.authorize(actor,p)]);assert.equal(results.filter(v=>v.status==='fulfilled'&&v.value.ok).length,1);assert.equal(results.filter(v=>v.status==='rejected').length,1);assert.equal(f.runtime.inspect().lookup_attempts,0);}finally{await f.close();}});
test('C07 context compound key comes from final genuine subject and admitted scalar slot',async()=>{const own='ReviewDesk.ApproveOwnedRequestEntry',read='ReviewDesk.ReadOwnedRequestEntry',f=await setup({source:text('context-request.alch'),rows:json('context-fixture-rows.json'),subjects:[subject,'fixture-reviewer-b'],grants:[own,read]});try{for(const[id,total]of[[subject,'20'],['fixture-reviewer-b','30']]){const expected=clone(oracle.business_cases[0].expected_outcome);expected.value.total=total;expected.value.result.fields.total=total;good(await invoke(f,own,{id:'23'},f.auth.actor(f.runtime,id,own)),expected);}assert.equal(f.runtime.inspect().lookup_attempts,2);}finally{await f.close();}});
test('C07 fixture invalid final row rolls back earlier valid rows and consumes loader',async()=>{const f=await setup({load:false});try{const bad=clone(rows);bad.rows[bad.rows.length-1].value.value.verified='true';assert.throws(()=>f.api.loadGenericFixture(f.fixture,wire(bad)));assert.throws(()=>f.api.loadGenericFixture(f.fixture,wire(rows)));good(await invoke(f,query),{kind:'Returned',value:null});}finally{await f.close();}});
for(const key of ['id','reference'])test('C07 duplicate '+key+' in fixture batch rolls back atomically',async()=>{const f=await setup({load:false});try{const bad=clone(rows);bad.rows[1].value[key]=bad.rows[0].value[key];assert.throws(()=>f.api.loadGenericFixture(f.fixture,wire(bad)));good(await invoke(f,query),{kind:'Returned',value:null});assert.throws(()=>f.api.loadGenericFixture(f.fixture,wire(rows)));}finally{await f.close();}});
test('C07 empty fixture batch succeeds once and consumes setup handle',async()=>{const f=await setup({load:false});try{f.api.loadGenericFixture(f.fixture,wire({...rows,rows:[]}));assert.throws(()=>f.api.loadGenericFixture(f.fixture,wire(rows)));good(await invoke(f,query),{kind:'Returned',value:null});}finally{await f.close();}});
for(const bytes of [new TextEncoder().encode('{'),wire({...rows,sql:'select 1'}),wire({...rows,rows:Array(101).fill(rows.rows[0])})])test('C07 malformed or overbound fixture rejects closed batch '+sha(Buffer.from(bytes)).slice(0,8),async()=>{const f=await setup({load:false});try{assert.throws(()=>f.api.loadGenericFixture(f.fixture,bytes));assert.throws(()=>f.api.loadGenericFixture(f.fixture,wire(rows)));good(await invoke(f,query),{kind:'Returned',value:null});}finally{await f.close();}});
test('C07 copied fixture loader cannot confer setup or partial data authority',async()=>{const f=await setup({load:false});try{assert.throws(()=>f.api.loadGenericFixture({...f.fixture},wire(rows)));f.api.loadGenericFixture(f.fixture,wire(rows));good(await invoke(f),oracle.business_cases[0].expected_outcome);}finally{await f.close();}});
test('C07 exclusive lock at schema acquisition is unavailable before keyed SELECT',async()=>{const f=await setup();const db=new DatabaseSync(f.storePath);try{f.runtime.assertCurrent();db.exec('BEGIN EXCLUSIVE');good(await invoke(f),{kind:'Failed',code:'storage-unavailable'});assert.equal(f.runtime.inspect().lookup_attempts,1);assert.equal(f.runtime.inspect().keyed_statement_attempts,0);db.exec('ROLLBACK');good(await invoke(f),oracle.business_cases[0].expected_outcome);db.exec('BEGIN EXCLUSIVE');db.exec('ROLLBACK');}finally{try{db.exec('ROLLBACK');}catch{}db.close();await f.close();}});
test('C07 same store reopens through real runtime without recreating fixture loader',async()=>{const f=await setup();try{const oldActor=f.auth.actor(f.runtime,subject,wrapper);await f.runtime.close();const reopened=await f.owner.openRuntime(f.handle,{service:'ReviewDeskService',storePath:f.storePath,mode:'reopen',nativeAuth:f.auth.nativeAuth});const original=f.runtime;f.runtime=reopened;try{await assert.rejects(async()=>invoke(f,wrapper,{id:'23'},oldActor));good(await invoke(f),oracle.business_cases[0].expected_outcome);assert.throws(()=>f.api.loadGenericFixture(f.fixture,wire(rows)));}finally{await reopened.close();f.runtime=original;}}finally{await f.close();}});
for(const target of ['source','profile','bounds','decision'])test('C07 '+target+' drift invalidates prepared runtime before protected read',async()=>{const f=await setup();try{const selected=target==='source'?f.sourcePath:target==='profile'?f.profilePath:target==='bounds'?path.join(f.dir,'contracts/bounds.json'):path.join(f.dir,'decision.json');writeFileSync(selected,readFileSync(selected,'utf8')+'\n');assert.throws(()=>f.runtime.assertCurrent());await assert.rejects(async()=>invoke(f));}finally{await f.close();}});
test('C07 generated source bundle imports only the actual installed package',async()=>{const f=await fixture();try{const out=path.join(f.dir,'generated'),manifest=await f.owner.generate(f.handle,{entry:wrapper,outputDirectory:out});recordArtifacts(out,manifest);const body=readFileSync(path.join(out,'application.mjs'),'utf8');assert.match(body,/@domainspec-v2\/cli\/generic/);assert.doesNotMatch(body,/file:\/\/|\.ts['"]|ALCHLANG_DOMAINSPEC_PACKAGE_ROOT/);assert.equal(body.includes(root),false);assert.match(body,/createGeneratedApplicationOwner/);assert.equal(existsSync(path.join(out,'operation.mjs')),false);}finally{f.cleanup();}});
test('C07 CLI exclusive entry selector generates actual reviewed bundle',async()=>{const f=await fixture();try{const out=path.join(f.dir,'cli-generated'),r=spawnSync(process.execPath,['--import','tsx',path.join(root,'language/capabilities/alchlang/plans/general-compiler-v1/implementation/src/generic-composition-cli.ts'),'generate','--source',f.sourcePath,'--profile',f.profilePath,'--entry',wrapper,'--out',out,'--accept-local-review','C07-independent-cli'],{cwd:cli,encoding:'utf8',timeout:120000,env:{...process.env,ALCHLANG_DOMAINSPEC_PACKAGE_ROOT:cli}});assert.equal(r.status,0,r.stderr+'\n'+r.stdout);recordArtifacts(out,JSON.parse(readFileSync(path.join(out,'manifest.json'),'utf8')));assert.equal(existsSync(path.join(out,'application.mjs')),true);}finally{f.cleanup();}});
for(const selection of [{entry:wrapper,operation:'ReviewDesk.ApproveRequest'},{entry:wrapper,rule:'ReviewDesk.IsVerified'},{entry:'ReviewDesk.UnknownEntry'}])test('C07 selector integrity '+JSON.stringify(selection),async()=>{const f=await fixture();try{const out=path.join(f.dir,'forbidden');await assert.rejects(async()=>f.owner.generate(f.handle,{...selection,outputDirectory:out}));assert.equal(existsSync(out),false);}finally{f.cleanup();}});
test('C07 unreviewed or copied composition never generates application',async()=>{const f=await fixture(source,profile,bounds,false);try{for(const h of[f.handle,{...f.handle}])await assert.rejects(async()=>f.owner.generate(h,{entry:wrapper,outputDirectory:path.join(f.dir,'forbidden')}));assert.equal(existsSync(path.join(f.dir,'forbidden')),false);}finally{f.cleanup();}});
for(const[before,after]of [[qWhere,'  where stored.value.verified'],[qWhere,'  where stored.id + 0 == id'],['  return ApproveRequest(request)','  return ApproveStoredRequest(id)']])test('C07 unsupported non-keyed or recursive source '+after,async()=>rejectSource(source.replace(before,after),after.includes('ApproveStoredRequest')?'InvalidContract':'UnsupportedCapability'));
test('C07 prior C06 profile rejects real Entity Query Entry declarations',async()=>{const old=JSON.parse(readFileSync(path.join(base,'contracts/C06/profile.json'),'utf8'));await rejectSource(source,'UnsupportedCapability',old);});
for(const mutate of [(p:any)=>({...p,unknown:true}),(p:any)=>({...p,auth_route_template:'generic:{logical_entry_id}'}),(p:any)=>({...p,services:[...p.services,...p.services]}),(p:any)=>({...p,capabilities:[...p.capabilities,'InventedCapability']})])test('C07 closed profile recipe rejects '+sha(mutate.toString()).slice(0,8),async()=>{await assert.rejects(()=>fixture(source,mutate(clone(profile))),(e:any)=>code(e)==='InvalidContract');});
test('C07 source/profile limits mismatch cannot silently replace authored budget',async()=>{const p=clone(profile);p.limits.fuel--;await assert.rejects(()=>fixture(source,p),(e:any)=>code(e)==='InvalidContract');});
test('C07 permission must equal authored resource and action',async()=>rejectSource(source.replace('    permission review.read','    permission other.read'),'InvalidContract'));
function extraQuery(name:string,type:string,expression:string){return `\nquery ${name}:\n  input id UInt64\n  source stored StoredRequest\n  output optional<${type}>\n  where stored.id == id\n  project ${expression}\n  on-missing return none\n  on-unavailable fail read-unavailable\n\nentry ReviewDesk.${name}Entry:\n  invokes ReviewDesk.${name}\n  interaction request-response\n  access:\n    authenticated customer\n    permission review.read\n    auth-resource review\n    auth-action read\n    auth-scope review-desk\n`;}
test('C07 declared version field remains readable business data',async()=>{const e='ReviewDesk.ReadVersionEntry',f=await setup({source:source+extraQuery('ReadVersion','UInt64','stored.version'),grants:[...entries,e]});try{good(await invoke(f,e),{kind:'Returned',value:'7'});}finally{await f.close();}});
for(const[name,type,expression,expected]of [['ReadFalse','Bool','false',false],['ReadEmpty','List<UInt64,8>','[]',[]]]as const)test('C07 '+name+' present projection is not classified as missing',async()=>{const e='ReviewDesk.'+name+'Entry',f=await setup({source:source+extraQuery(name,type,expression),grants:[...entries,e]});try{good(await invoke(f,e),{kind:'Returned',value:expected});good(await invoke(f,e,{id:'99'}),{kind:'Returned',value:null});}finally{await f.close();}});
const fallbackRequest='Request(verified=true,flagged=false,requestId=id,state=Draft,signal=Submit,items=[],note=none)';
const fallbackDecision={kind:'Returned',value:{approved:true,decisionId:'99',proposal:{tag:'transition',state:'Approved',intents:[],machine:'ReviewDesk.Approval',branch:'transition:0',reason:'matched'},items:[],scores:[],total:'0',result:{tag:'Scored',fields:{total:'0'}},note:null}};
test('C07 missing fallback returning some executes original Operation instead of caller missing',async()=>{const f=await setup({source:queryEdit('  on-missing return none','  on-missing return some('+fallbackRequest+')')});try{good(await invoke(f,wrapper,{id:'99'}),fallbackDecision);}finally{await f.close();}});
