const sqlName=(name:string)=>'"'+name.replaceAll('"','""')+'"';
function storage(f:any){const descriptor=f.runtime.inspect().storage;assert.equal(descriptor.schema_version,'craft.generic-sqlite-storage/v1-candidate');assert.equal(descriptor.authority_effect,'none');assert.equal(descriptor.service,'ReviewDeskService');const table=descriptor.tables.find((t:any)=>t.entity==='ReviewDesk.StoredRequest');assert.ok(table);const column=(name:string)=>{const c=table.columns.find((c:any)=>c.name===name);assert.ok(c);return c.sql_name;};return{descriptor,table,column};}
function storageFault(r:any,cause:string){fault(r,'StorageDataInvalid');assert.equal(r.error.cause.code,cause);assert.equal(r.error.site.entity,'ReviewDesk.StoredRequest');assert.equal(r.error.site.query,'ReviewDesk.ReadRequest');assert.ok(r.error.site.path.length>0);assert.equal(JSON.stringify(r).includes('C07-CORRUPT-SENTINEL'),false);return r;}
