test('C07 original selected native registry cannot be poisoned through returned state or inspection',async()=>{const dir=mkdtempSync(path.join(tmpdir(),'craft-independent-C07-native-'));let native:any;try{const assetApi=await import('../../src/generic/auth-asset.js'),bridge=await import('../../src/commerce/commerce-auth-ready-bridge-v1.js'),asset=assetApi.loadOriginalGenericAuthAsset(path.join(dir,'selected')),state:any=assetApi.assertGenericSelectedAuthAsset(asset),expected=state.binary,binaryHash=sha(readFileSync(expected));assert.throws(()=>assetApi.assertGenericSelectedAuthAsset({...asset}),(e:any)=>code(e)==='ForeignOwner');const poison=path.join(dir,'never-executed-poison');for(const [object,key,value]of [[state,'binary',poison],[state,'current',()=>{}],[state,'files',[]],[state.files[1],'path',poison],[state.manifest.asset_manifest.binary,'path',poison]] as const){try{Reflect.set(object,key,value);}catch{}}assert.equal(assetApi.assertGenericSelectedAuthAsset(asset).binary,expected);native=bridge.createCommerceAuthNativeOwnerFromSelectedAsset(asset);const inspected:any=native.inspect();try{Reflect.set(inspected.asset_manifest.binary,'sha256','0'.repeat(64));}catch{}assert.equal((native.inspect() as any).asset_manifest.binary.sha256,binaryHash);native.assertCurrent();const dbHandle=bridge.createCommerceAuthFixtureDatabaseV1(native),location=bridge.inspectCommerceAuthFixtureDatabaseV1(native,dbHandle),db=new DatabaseSync(location.file);try{db.exec(readFileSync(state.migration,'utf8'));}finally{db.close();}chmodSync(location.file,0o600);bridge.sealCommerceAuthFixtureDatabaseV1(native,dbHandle);const request={abi:bridge.COMMERCE_AUTH_READY_ABI_V1,request:{request_id:'independent-native-custody',authentication_evidence_ref:'absent-evidence',route_id:'commerce:'+query},binding:{invocation_id:'independent-native-custody',logical_entry_id:query,bound_operation_id:'ReviewDesk.ReadRequest',canonical_input_sha256:'1'.repeat(64),checked_source_sha256:'2'.repeat(64),profile_config_sha256:'3'.repeat(64),native_basis_sha256:'4'.repeat(64),actor_owner_identity:'independent-actor',causal_owner_identity:null,target_service_id:'ReviewDeskService',store_or_event_epoch:'independent-store'},expected_permission:{resource:'review',action:'read',scope:'review-desk'}};const completion=await native.execute(dbHandle,request),result=native.inspectCompletion(completion);assert.equal(result.response.abi,bridge.COMMERCE_AUTH_READY_ABI_V1);assert.equal(result.response.outcome,'deny');assert.equal(result.response.ready,null);assert.equal(sha(readFileSync(expected)),binaryHash);assert.equal(existsSync(poison),false);native.assertCurrent();}finally{if(native)await native.dispose();rmSync(dir,{recursive:true,force:true});}});
