// Intrinsic fixture-byte controls: wrappers contain finite throwing hooks only.
function hostileFixtureBytes(contents:Uint8Array){class HostileBytes extends Uint8Array{}const value=new HostileBytes(contents.length);Uint8Array.prototype.set.call(value,contents);let hits=0;for(const key of ['byteLength','byteOffset','buffer','length',Symbol.iterator])Object.defineProperty(value,key,{configurable:true,get(){hits++;throw new Error('fixture wrapper hook must not run');}});return{value,hits:()=>hits};}
